import { scaleLinear } from "d3-scale";

/** A value domain, low to high. */
export type Domain = readonly [number, number];

export type NiceScaleOptions = {
  /** Keep zero inside the domain. Bars and areas need it; lines may drop it. Default true. */
  zero?: boolean;
  /** Roughly how many gridlines. Default 4. */
  ticks?: number;
};

/**
 * A clean value domain and its gridline values for a set of numbers: rounded to tick steps
 * (0 / 2K / 4K …), zero kept by default, and a flat or empty series still gets a usable range.
 */
export function niceScale(values: Iterable<number>, { zero = true, ticks = 4 }: NiceScaleOptions = {}) {
  let lo = Infinity;
  let hi = -Infinity;
  for (const v of values) {
    if (!Number.isFinite(v)) continue;
    if (v < lo) lo = v;
    if (v > hi) hi = v;
  }
  if (lo === Infinity) [lo, hi] = [0, 1];
  if (zero) [lo, hi] = [Math.min(0, lo), Math.max(0, hi)];
  if (lo === hi) [lo, hi] = lo === 0 ? [0, 1] : [lo - Math.abs(lo) * 0.1, hi + Math.abs(hi) * 0.1];
  // d3's tick count is a hint; step it down until there are at most `ticks + 1` lines.
  for (let count = ticks; ; count--) {
    const scale = scaleLinear().domain([lo, hi]).nice(count);
    const t = scale.ticks(count);
    if (t.length <= ticks + 1 || count <= 1) {
      const [a, b] = scale.domain();
      return { domain: [a, b] as Domain, ticks: t };
    }
  }
}

/** Maps a value in `domain` to a pixel in `range`; `range` may run high to low (y grows down). */
export function linear(domain: Domain, range: Domain) {
  const [d0, d1] = domain;
  const [r0, r1] = range;
  const k = d1 === d0 ? 0 : (r1 - r0) / (d1 - d0);
  return (v: number) => r0 + (v - d0) * k;
}

export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

/**
 * Which of `count` evenly spaced x labels to show at `width`: at most one per `minGap` px
 * (Arc's 76), always keeping the newest, then stepping back from it so the gaps stay even.
 */
export function thinLabels(count: number, width: number, minGap = 76): number[] {
  if (count <= 0) return [];
  if (count === 1) return [0];
  const spacing = width / (count - 1);
  const step = Math.max(1, Math.ceil(minGap / Math.max(spacing, 0.0001)));
  const out: number[] = [];
  for (let i = count - 1; i >= 0; i -= step) out.unshift(i);
  return out;
}

/** Evenly spaced bands for bars: the band width, each band's left edge, and a bar width capped at 24px with ≥ 2px air. */
export function bands(count: number, width: number, { maxBar = 24, gap = 0.32 }: { maxBar?: number; gap?: number } = {}) {
  const band = count > 0 ? width / count : width;
  const bar = Math.max(1, Math.min(maxBar, band - Math.max(2, band * gap)));
  return { band, bar, left: (i: number) => i * band, center: (i: number) => i * band + band / 2 };
}

"use client";

import { useLayoutEffect, useRef, useState, type RefObject } from "react";

export type ChartSize = { width: number; height: number };

/**
 * The content-box size of an element, kept current with a ResizeObserver and rounded to
 * whole pixels so sub-pixel jitter never re-renders a chart. 0 × 0 until measured (and on the
 * server), so draw nothing until `width > 0`.
 */
export function useChartSize<T extends HTMLElement = HTMLDivElement>(): [RefObject<T | null>, ChartSize] {
  const ref = useRef<T>(null);
  const [size, setSize] = useState<ChartSize>({ width: 0, height: 0 });

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const update = (width: number, height: number) => {
      const w = Math.round(width);
      const h = Math.round(height);
      setSize((s) => (s.width === w && s.height === h ? s : { width: w, height: h }));
    };
    const rect = el.getBoundingClientRect();
    update(rect.width, rect.height);
    const ro = new ResizeObserver(([entry]) => update(entry.contentRect.width, entry.contentRect.height));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  return [ref, size];
}

"use client";

import { animate, type AnimationPlaybackControls, type Transition } from "motion/react";
import { useLayoutEffect, useRef, useState } from "react";
import { smooth } from "../../lib/motion";
import { lerp, type Domain } from "./scales";

export type Curve = "monotone" | "linear";

/* ---------- Sampling ------------------------------------------------------- */

// d3-shape's curveMonotoneX tangents (Steffen 1990) for evenly spaced points, so a sampled
// curve is the exact curve d3 would draw. With x evenly spaced the Bézier's x is linear in t,
// so each segment is a cubic Hermite in y and can be evaluated at any x directly.
function tangents(v: readonly number[]) {
  const n = v.length;
  const t = new Float64Array(n);
  if (n < 2) return t;
  const s = (i: number) => v[i + 1] - v[i]; // secant over one step
  for (let i = 1; i < n - 1; i++) {
    const s0 = s(i - 1);
    const s1 = s(i);
    const p = (s0 + s1) / 2;
    t[i] = (Math.sign(s0) + Math.sign(s1)) * Math.min(Math.abs(s0), Math.abs(s1), 0.5 * Math.abs(p)) || 0;
  }
  t[0] = n > 2 ? (3 * s(0) - t[1]) / 2 : s(0);
  t[n - 1] = n > 2 ? (3 * s(n - 2) - t[n - 2]) / 2 : s(0);
  return t;
}

/**
 * Samples a series of evenly spaced values at `count` evenly spaced positions across the
 * same span, along a monotone (d3 `curveMonotoneX`) or straight curve. Two series with
 * different lengths sampled at the same `count` share their x positions: that is what lets
 * a 7-point line morph into a 30-point one without inventing or dropping vertices.
 */
export function sampleSeries(values: readonly number[], count: number, curve: Curve = "monotone"): Float64Array {
  const out = new Float64Array(count);
  const n = values.length;
  if (n === 0) return out;
  if (n === 1 || count === 1) return out.fill(n === 1 ? values[0] : values[n - 1]);
  const t = curve === "monotone" ? tangents(values) : null;
  for (let k = 0; k < count; k++) {
    const pos = (k / (count - 1)) * (n - 1);
    const i = Math.min(n - 2, Math.floor(pos));
    const u = pos - i;
    const y0 = values[i];
    const y1 = values[i + 1];
    if (!t) {
      out[k] = y0 + (y1 - y0) * u;
      continue;
    }
    const u2 = u * u;
    const u3 = u2 * u;
    out[k] = (2 * u3 - 3 * u2 + 1) * y0 + (u3 - 2 * u2 + u) * t[i] + (-2 * u3 + 3 * u2) * y1 + (u3 - u2) * t[i + 1];
  }
  return out;
}

/** The sampled value at `u` ∈ [0, 1] along a sampled series (linear between samples). */
export function sampleAt(samples: ArrayLike<number>, u: number) {
  const n = samples.length;
  if (n === 0) return 0;
  if (n === 1) return samples[0];
  const pos = Math.max(0, Math.min(1, u)) * (n - 1);
  const i = Math.min(n - 2, Math.floor(pos));
  return lerp(samples[i], samples[i + 1], pos - i);
}

function resample(samples: Float64Array, count: number) {
  if (samples.length === count) return samples;
  const out = new Float64Array(count);
  for (let k = 0; k < count; k++) out[k] = sampleAt(samples, count === 1 ? 1 : k / (count - 1));
  return out;
}

const round = (n: number) => Math.round(n * 100) / 100;

/** An SVG path through the samples. `x(u)` maps 0–1 across the plot, `y(v)` a value to a pixel. */
export function samplesToPath(samples: ArrayLike<number>, x: (u: number) => number, y: (v: number) => number) {
  const n = samples.length;
  if (n === 0) return "";
  let d = "";
  for (let k = 0; k < n; k++) d += `${k ? "L" : "M"}${round(x(n === 1 ? 1 : k / (n - 1)))},${round(y(samples[k]))}`;
  return d;
}

/** The same line closed down to `baseY`, for an area fill. */
export function samplesToArea(samples: ArrayLike<number>, x: (u: number) => number, y: (v: number) => number, baseY: number) {
  if (samples.length === 0) return "";
  return `${samplesToPath(samples, x, y)}L${round(x(1))},${round(baseY)}L${round(x(0))},${round(baseY)}Z`;
}

/** Where a series rests when it enters or leaves: zero if the domain holds it, else the nearer edge. */
export const baselineOf = ([lo, hi]: Domain) => Math.min(hi, Math.max(lo, 0));

/* ---------- useMorphPath --------------------------------------------------- */

/** What the chart should show: each series' values (evenly spaced in x) and the value domain. */
export type MorphShape = { series: Readonly<Record<string, readonly number[]>>; domain: Domain };
/** What is on screen this frame: every series sampled on shared x positions, and the domain. */
export type MorphFrame = { series: Record<string, Float64Array>; domain: Domain };

export type UseMorphPathOptions = {
  /** Draws a frame: write `d` attributes and move gridlines here. Called outside React render. */
  onFrame: (frame: MorphFrame) => void;
  /** Shared x samples per series. Default 160; keep ≥ 8 per data segment for smooth curves. */
  samples?: number;
  curve?: Curve;
  /** The morph's transition. Default `smooth` (no overshoot: data should not wobble past its value). */
  transition?: Transition;
  /** False jumps to every new shape (reduced motion, scrubbing a slider). Default true. */
  animate?: boolean;
};

const signature = (shape: MorphShape, count: number, curve: Curve) => {
  let s = `${count}|${curve}|${shape.domain[0]},${shape.domain[1]}`;
  for (const key of Object.keys(shape.series)) s += `|${key}:${shape.series[key].join(",")}`;
  return s;
};

/**
 * Morphs a set of paths between shapes the way Arc does, without React re-rendering a frame:
 * every series is resampled onto the same x positions, so any shape tweens into any other
 * point for point, and the value domain rides the same progress so gridlines and lines stay
 * in register. A change mid-morph starts from what is on screen. Series that appear grow out
 * of the baseline; series that leave flatten into it and are then dropped from the frame.
 *
 *   const morph = useMorphPath({ series: { revenue }, domain }, { onFrame: (f) => {
 *     line.current?.setAttribute("d", samplesToPath(f.series.revenue, x, y));
 *   }});
 *
 * Returns `get()` (the current frame) and `redraw()` (re-emit it, e.g. after a resize).
 */
export function useMorphPath(shape: MorphShape, { onFrame, samples = 160, curve = "monotone", transition = smooth, animate: animated = true }: UseMorphPathOptions) {
  const frame = useRef<MorphFrame | null>(null);
  const anim = useRef<AnimationPlaybackControls | null>(null);
  const draw = useRef(onFrame);
  const shapeRef = useRef(shape);
  const options = useRef({ samples, curve, transition, animated });
  useLayoutEffect(() => {
    draw.current = onFrame;
    shapeRef.current = shape;
    options.current = { samples, curve, transition, animated };
  });

  const key = signature(shape, samples, curve);
  useLayoutEffect(() => {
    const { samples: count, curve: c, transition: tr, animated: anime } = options.current;
    const next = shapeRef.current;
    const target: MorphFrame = { series: {}, domain: next.domain };
    for (const k of Object.keys(next.series)) target.series[k] = sampleSeries(next.series[k], count, c);

    const from = frame.current;
    anim.current?.stop();
    if (!from || !anime) {
      frame.current = target;
      draw.current(target);
      return;
    }

    const keys = new Set([...Object.keys(from.series), ...Object.keys(target.series)]);
    const a: Record<string, Float64Array> = {};
    const b: Record<string, Float64Array> = {};
    for (const k of keys) {
      a[k] = from.series[k] ? resample(from.series[k], count) : new Float64Array(count).fill(baselineOf(from.domain));
      b[k] = target.series[k] ?? new Float64Array(count).fill(baselineOf(target.domain));
    }
    const live: MorphFrame = { series: {}, domain: from.domain };
    for (const k of keys) live.series[k] = new Float64Array(count);

    anim.current = animate(0, 1, {
      ...tr,
      onUpdate: (p) => {
        for (const k of keys) {
          const out = live.series[k];
          const s0 = a[k];
          const s1 = b[k];
          for (let i = 0; i < count; i++) out[i] = s0[i] + (s1[i] - s0[i]) * p;
        }
        live.domain = [lerp(from.domain[0], target.domain[0], p), lerp(from.domain[1], target.domain[1], p)];
        frame.current = live;
        draw.current(live);
      },
      onComplete: () => {
        frame.current = target;
        draw.current(target);
      },
    });
  }, [key]);

  useLayoutEffect(() => () => anim.current?.stop(), []);

  const [api] = useState(() => ({
    get: () => frame.current,
    redraw: () => {
      if (frame.current) draw.current(frame.current);
    },
  }));
  return api;
}

"use client";

import { animate, motion, useMotionValue, type MotionValue, type Transition } from "motion/react";
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type CSSProperties,
  type FocusEvent,
  type KeyboardEvent,
  type PointerEvent,
  type ReactNode,
} from "react";
import { enter, exitFast, instant, smooth, snappy } from "../../lib/motion";

/* ---------- Active index store --------------------------------------------- */

/**
 * The scrubbed index, outside React state: the plot never re-renders while you scrub.
 * Only the pieces that show the value (tooltip, headline) subscribe.
 */
export type ActiveStore = {
  get(): number | null;
  set(index: number | null): void;
  subscribe(listener: () => void): () => void;
};

export function createActiveStore(): ActiveStore {
  let value: number | null = null;
  const listeners = new Set<() => void>();
  return {
    get: () => value,
    set(next) {
      if (next === value) return;
      value = next;
      for (const l of listeners) l();
    },
    subscribe(l) {
      listeners.add(l);
      return () => listeners.delete(l);
    },
  };
}

/** One store per chart, stable across renders. */
export function useActiveStore() {
  const [store] = useState(createActiveStore);
  return store;
}

/** Subscribe a component to the scrubbed index (re-renders only that component). */
export function useActiveIndex(store: ActiveStore) {
  return useSyncExternalStore(store.subscribe, store.get, () => null);
}

/* ---------- Scrub: pointer, keyboard, crosshair ---------------------------- */

export type UseChartScrubOptions = {
  /** Number of points (or bars). */
  count: number;
  store: ActiveStore;
  /** The pixel x of point `i`, relative to the scrub surface. */
  xOf: (index: number) => number;
  /** The nearest index to a pixel x on the scrub surface. */
  indexAt: (x: number) => number;
  /** What a screen reader hears for point `i`: date, then every visible value. */
  valueText: (index: number) => string;
  /** The figure's name, e.g. "Revenue, last 30 days". */
  label: string;
  onActiveChange?: (index: number | null) => void;
  reduced?: boolean;
  /** How the crosshair glides between points. Default `snappy`. */
  transition?: Transition;
};

/**
 * The interaction model every Eased chart shares (Arc's, kept): the plot is one
 * `role="slider"` whose value is the scrubbed point. Pointer and touch scrub it (vertical
 * page scroll still works); arrows step, PageUp/PageDown jump a tenth, Home/End go to the
 * ends, Escape lets go. `aria-valuetext` reads the date and every value, updated in place.
 *
 * Returns props to spread on the scrub surface (a div exactly over the plot) and the
 * crosshair's motion values: `x` glides to the active point, `opacity` fades it in and out.
 */
export function useChartScrub({ count, store, xOf, indexAt, valueText, label, onActiveChange, reduced = false, transition = snappy }: UseChartScrubOptions) {
  const ref = useRef<HTMLDivElement>(null);
  const x = useMotionValue(0);
  const opacity = useMotionValue(0);
  const latest = useRef({ count, xOf, valueText, onActiveChange, reduced, transition });
  useLayoutEffect(() => {
    latest.current = { count, xOf, valueText, onActiveChange, reduced, transition };
  });

  // Follow the store: glide the crosshair, keep ARIA current, notify.
  useEffect(() => {
    let shown = store.get() !== null;
    const sync = () => {
      const i = store.get();
      const { xOf, valueText, onActiveChange, reduced, transition, count } = latest.current;
      const el = ref.current;
      if (el && count > 0) {
        const now = i ?? count - 1;
        el.setAttribute("aria-valuenow", String(now));
        el.setAttribute("aria-valuetext", valueText(now));
      }
      if (i === null) {
        animate(opacity, 0, reduced ? instant : exitFast);
        shown = false;
      } else {
        const target = xOf(i);
        if (!shown || reduced) x.jump(target);
        else animate(x, target, transition);
        animate(opacity, 1, reduced ? instant : { duration: 0.12 });
        shown = true;
      }
      onActiveChange?.(i);
    };
    return store.subscribe(sync);
  }, [store, x, opacity]);

  // Data or size changed under an active point: clamp it and re-seat the crosshair.
  useLayoutEffect(() => {
    const i = store.get();
    if (i === null) return;
    if (i > count - 1) store.set(count > 0 ? count - 1 : null);
    else animate(x, xOf(i), reduced ? instant : smooth);
  }, [count, xOf, store, x, reduced]);

  const fromPointer = useCallback(
    (e: PointerEvent<HTMLDivElement>) => {
      const rect = e.currentTarget.getBoundingClientRect();
      const i = indexAt(e.clientX - rect.left);
      store.set(Math.max(0, Math.min(count - 1, i)));
    },
    [count, indexAt, store],
  );

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (count === 0) return;
    const i = store.get() ?? count - 1;
    const page = Math.max(1, Math.round(count / 10));
    const next: Record<string, number | null> = {
      ArrowRight: i + 1,
      ArrowUp: i + 1,
      ArrowLeft: i - 1,
      ArrowDown: i - 1,
      PageUp: i + page,
      PageDown: i - page,
      Home: 0,
      End: count - 1,
      Escape: null,
    };
    if (!(e.key in next)) return;
    e.preventDefault();
    const n = next[e.key];
    store.set(n === null ? null : Math.max(0, Math.min(count - 1, n)));
  };

  const last = Math.max(0, count - 1);
  const props = {
    ref,
    role: "slider",
    tabIndex: count > 0 ? 0 : -1,
    "aria-label": label,
    "aria-valuemin": 0,
    "aria-valuemax": last,
    "aria-valuenow": last,
    "aria-valuetext": count > 0 ? valueText(last) : undefined,
    "aria-orientation": "horizontal" as const,
    onKeyDown,
    onFocus: (e: FocusEvent<HTMLDivElement>) => {
      // Keyboard focus lands on the newest point; pointer focus is handled by the pointer.
      if (e.currentTarget.matches(":focus-visible") && store.get() === null && count > 0) store.set(count - 1);
    },
    onBlur: () => store.set(null),
    onPointerDown: fromPointer,
    onPointerMove: fromPointer,
    onPointerLeave: () => store.set(null),
    onPointerCancel: () => store.set(null),
    style: { touchAction: "pan-y" } as CSSProperties,
  };

  return { props, x, opacity };
}

/* ---------- Tooltip -------------------------------------------------------- */

export type ChartTooltipProps = {
  store: ActiveStore;
  /** The pixel x of point `i`, in the same coordinates as the tooltip's container. */
  xOf: (index: number) => number;
  /** The container's width; the tooltip flips to the left of the point before it overflows. */
  width: number;
  /** Gap between the point and the tooltip, px. Default 12. */
  offset?: number;
  /** Distance from the container's top, px. Default 0. */
  top?: number;
  reduced?: boolean;
  /** The content for point `i`. Re-rendered only while scrubbing, and only here. */
  children: (index: number) => ReactNode;
  className?: string;
};

/**
 * A floating readout that follows the scrubbed point on its own `smooth` spring, a beat
 * behind the crosshair, and flips sides before it would leave the plot. It keeps showing the
 * last point while it fades out, so content never blanks mid-exit. `aria-hidden`: the slider
 * already reads the same values.
 */
export function ChartTooltip({ store, xOf, width, offset = 12, top = 0, reduced = false, children, className = "" }: ChartTooltipProps) {
  const index = useActiveIndex(store);
  const [shown, setShown] = useState<number | null>(null);
  const el = useRef<HTMLDivElement>(null);
  const x = useMotionValue(0);
  const visible = useRef(false);
  if (index !== null && index !== shown) setShown(index);

  useLayoutEffect(() => {
    if (index === null || !el.current) {
      visible.current = false;
      return;
    }
    const w = el.current.offsetWidth;
    const px = xOf(index);
    const right = px + offset + w <= width;
    const target = Math.max(0, Math.min(width - w, right ? px + offset : px - offset - w));
    if (!visible.current || reduced) x.jump(target);
    else animate(x, target, smooth);
    visible.current = true;
  }, [index, xOf, width, offset, reduced, x]);

  return (
    <motion.div
      ref={el}
      aria-hidden
      className={`pointer-events-none absolute left-0 z-10 rounded-control border border-line bg-surface-raised px-3 py-2 text-ui-xs text-text shadow-floating ${className}`}
      style={{ x, top }}
      initial={false}
      animate={index === null ? { opacity: 0, scale: 0.97 } : { opacity: 1, scale: 1 }}
      transition={reduced ? instant : index === null ? exitFast : enter}
    >
      {shown !== null && children(shown)}
    </motion.div>
  );
}

/** The crosshair's motion values, for a vertical rule in the plot's `<svg>`. */
export function Crosshair({ x, opacity, height, top = 0 }: { x: MotionValue<number>; opacity: MotionValue<number>; height: number; top?: number }) {
  return (
    <motion.line
      aria-hidden
      x1={0}
      x2={0}
      y1={top}
      y2={height}
      stroke="var(--eased-chart-cursor)"
      strokeWidth={1}
      style={{ x, opacity }}
      shapeRendering="crispEdges"
    />
  );
}

"use client";

import { AnimatePresence, motion, useMotionValueEvent, type MotionValue, type Transition } from "motion/react";
import { useLayoutEffect, useRef } from "react";
import { exitFast, fade, instant } from "../../lib/motion";
import { linear, type Domain } from "./scales";

export type ChartGridProps = {
  /** Gridline values, usually `niceScale(...).ticks`. */
  ticks: readonly number[];
  /** The live value domain. Gridlines ride it, so they slide while the scale springs. */
  domain: MotionValue<Domain>;
  /** Full width, px, gutter included. */
  width: number;
  /** Left gutter for the labels, px (see `gutterFor`). Lines start after it. Default 0: labels sit above the lines. */
  gutter?: number;
  /** Pixel range the domain maps to, top to bottom: `[top, bottom]`. */
  range: Domain;
  /** Tick label text. Leave out for unlabelled gridlines. */
  format?: (value: number) => string;
  reduced?: boolean;
};

/** A label gutter wide enough for the widest tick label (11px tabular figures), plus an 8px gap. */
export function gutterFor(labels: readonly string[]) {
  const longest = labels.reduce((m, l) => Math.max(m, l.length), 0);
  return longest ? Math.ceil(longest * 6.4) + 8 : 0;
}

/**
 * Hairline gridlines with their labels left-aligned on the chart's leading edge (the same x
 * as the headline and legend above it): in a gutter beside the lines, or just above them. When the domain changes, lines that
 * stay slide with the springing scale; new values fade in and retired ones fade out while
 * still sliding, so nothing pops. SVG; render it inside the plot's `<svg>`.
 */
export function ChartGrid({ ticks, domain, width, gutter = 0, range, format, reduced = false }: ChartGridProps) {
  return (
    <g aria-hidden>
      <AnimatePresence initial={false}>
        {ticks.map((t) => (
          <Tick key={t} value={t} domain={domain} width={width} gutter={gutter} range={range} label={format?.(t)} reduced={reduced} />
        ))}
      </AnimatePresence>
    </g>
  );
}

function Tick({ value, domain, width, gutter, range, label, reduced }: { value: number; domain: MotionValue<Domain>; width: number; gutter: number; range: Domain; label?: string; reduced: boolean }) {
  const ref = useRef<SVGGElement>(null);
  const place = (d: Domain) => {
    const y = Math.round(linear(d, [range[1], range[0]])(value)) + 0.5;
    ref.current?.setAttribute("transform", `translate(0 ${y})`);
  };
  useLayoutEffect(() => place(domain.get()));
  useMotionValueEvent(domain, "change", place);

  return (
    <motion.g
      ref={ref}
      initial={{ opacity: 0 }}
      animate={{ opacity: 1, transition: reduced ? instant : fade }}
      exit={{ opacity: 0, transition: reduced ? instant : exitFast }}
    >
      <line x1={gutter} x2={width} stroke="var(--eased-chart-grid)" strokeWidth={1} shapeRendering="crispEdges" />
      {label !== undefined && (
        <text y={gutter ? 0 : -6} dominantBaseline={gutter ? "central" : undefined} className="fill-text-muted tabular-nums" style={{ fontSize: 11 }}>
          {label}
        </text>
      )}
    </motion.g>
  );
}

export type ChartXAxisProps = {
  /** The labels to show (already thinned), each with its bucket's key and pixel x. */
  items: readonly { key: string; x: number; text: string; align?: "start" | "center" | "end" }[];
  /** Morph transition for labels that stay. */
  transition: Transition;
  reduced?: boolean;
  /** Left offset of the row, px: the plot's gutter. */
  left?: number;
  className?: string;
};

/**
 * X labels in an HTML row under the plot. Labels keyed by their bucket slide to their new
 * position when the range changes; others fade. The first label starts on the plot's left
 * line and the last ends on its right line (`align`), so neither clips and both edges stay true.
 */
export function ChartXAxis({ items, transition, reduced = false, left = 0, className = "" }: ChartXAxisProps) {
  return (
    <div aria-hidden className={`pointer-events-none h-4 text-ui-2xs text-text-muted tabular-nums ${className}`} style={{ left }}>
      <AnimatePresence initial={false}>
        {items.map((item) => {
          const shift = item.align === "start" ? "" : item.align === "end" ? "-translate-x-full" : "-translate-x-1/2";
          return (
            <motion.span
              key={item.key}
              className={`absolute top-0 left-0 whitespace-nowrap ${shift}`}
              initial={{ x: item.x, opacity: 0 }}
              animate={{ x: item.x, opacity: 1, transition: reduced ? instant : { x: transition, opacity: fade } }}
              exit={{ opacity: 0, transition: reduced ? instant : exitFast }}
            >
              {item.text}
            </motion.span>
          );
        })}
      </AnimatePresence>
    </div>
  );
}

"use client";

import type { ReactNode } from "react";
import { press } from "../../lib/press";

export type ChartKey = {
  key: string;
  label: string;
  /** CSS colour, usually `chartColor(n)`. */
  color: string;
  /** Previous-period style: a dashed line key. */
  dashed?: boolean;
};

/** A series' identity mark: a short line key for lines, a rounded square for bars and areas. */
export function ChartSwatch({ color, shape = "square", dashed = false, off = false }: { color: string; shape?: "line" | "square"; dashed?: boolean; off?: boolean }) {
  if (shape === "line") {
    return (
      <svg aria-hidden width={12} height={8} viewBox="0 0 12 8" className="shrink-0 overflow-visible">
        <line x1={1} x2={11} y1={4} y2={4} stroke={color} strokeWidth={2} strokeLinecap="round" strokeDasharray={dashed ? "2 3" : undefined} opacity={off ? 0.35 : dashed ? 0.6 : 1} />
      </svg>
    );
  }
  return (
    <span
      aria-hidden
      className="size-2 shrink-0 rounded-[calc(var(--eased-radius-control-2xs)/2)] transition-opacity duration-150 ease-standard"
      style={{ background: off ? "transparent" : color, boxShadow: off ? `inset 0 0 0 1.5px ${color}` : undefined, opacity: off ? 0.6 : 1 }}
    />
  );
}

export type ChartLegendProps = {
  items: readonly ChartKey[];
  /** Keys currently hidden. */
  hidden?: ReadonlySet<string>;
  /** Makes each key a toggle button. Leave out for a static legend. */
  onToggle?: (key: string) => void;
  /** Hovering or focusing a key previews it: the chart dims the others. */
  onPreview?: (key: string | null) => void;
  shape?: "line" | "square";
  /** Extra content on the right, e.g. a total. */
  trailing?: ReactNode;
  className?: string;
};

/**
 * The legend: always present for two or more series, so identity never rests on colour.
 * As toggles, each key is a pressed/unpressed button; the row is pulled left by the buttons'
 * padding so the first swatch sits on the content's left line (rule 104).
 */
export function ChartLegend({ items, hidden, onToggle, onPreview, shape = "square", trailing, className = "" }: ChartLegendProps) {
  return (
    <div className={`flex min-w-0 items-center justify-between gap-3 ${className}`}>
      <ul className={`flex min-w-0 flex-wrap items-center ${onToggle ? "-ml-2 gap-x-0.5" : "gap-x-4"} gap-y-1`}>
        {items.map((item) => {
          const off = hidden?.has(item.key) ?? false;
          const body = (
            <>
              <ChartSwatch color={item.color} shape={shape} dashed={item.dashed} off={off} />
              <span className="truncate">{item.label}</span>
            </>
          );
          return (
            <li key={item.key} className="min-w-0">
              {onToggle ? (
                <button
                  type="button"
                  aria-pressed={!off}
                  onClick={() => onToggle(item.key)}
                  onPointerEnter={(e) => e.pointerType === "mouse" && onPreview?.(item.key)}
                  onPointerLeave={() => onPreview?.(null)}
                  onFocus={() => onPreview?.(item.key)}
                  onBlur={() => onPreview?.(null)}
                  className={`${press} inline-flex h-6 max-w-full cursor-pointer items-center gap-1.5 rounded-control-xs px-2 text-ui-xs hover-fine:bg-surface-hover ${off ? "text-text-muted" : "text-text-secondary hover-fine:text-text"}`}
                >
                  {body}
                </button>
              ) : (
                <span className="inline-flex h-6 items-center gap-1.5 text-ui-xs text-text-secondary">{body}</span>
              )}
            </li>
          );
        })}
      </ul>
      {trailing}
    </div>
  );
}

import type { ReactNode } from "react";

export type ChartDataColumn<D> = {
  /** Column header, e.g. the series label. */
  label: string;
  /** The cell's text for a row. */
  value: (datum: D, index: number) => ReactNode;
};

export type ChartDataTableProps<D> = {
  /** What the table lists, e.g. "Revenue by day". */
  caption: string;
  data: readonly D[];
  /** The row header (usually the formatted date or category). */
  rowLabel: (datum: D, index: number) => ReactNode;
  /** Header of the row-label column. Default "Date". */
  rowLabelHeader?: string;
  columns: readonly ChartDataColumn<D>[];
};

/**
 * Every point of a chart as a real `<table>`, visually hidden. Screen reader users get the
 * whole dataset in table navigation, and anyone who cannot tell two hues apart has the
 * numbers. Pair it with an `aria-hidden` SVG.
 */
export function ChartDataTable<D>({ caption, data, rowLabel, rowLabelHeader = "Date", columns }: ChartDataTableProps<D>) {
  return (
    <table className="sr-only">
      <caption>{caption}</caption>
      <thead>
        <tr>
          <th scope="col">{rowLabelHeader}</th>
          {columns.map((c) => (
            <th key={c.label} scope="col">
              {c.label}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {data.map((d, i) => (
          <tr key={i}>
            <th scope="row">{rowLabel(d, i)}</th>
            {columns.map((c) => (
              <td key={c.label}>{c.value(d, i)}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

"use client";

import { animate, useInView, useMotionValue } from "motion/react";
import { useEffect, type RefObject } from "react";
import { ease } from "../../lib/motion";

export type DrawInOptions = {
  reduced?: boolean;
  /** Seconds. Default 0.9: a chart is read left to right, so it is drawn at reading pace. */
  duration?: number;
  delay?: number;
  /** Share of the chart that must be on screen. Default 0.35. */
  amount?: number;
};

/**
 * 0 → 1 once, the first time `ref` scrolls into view; then never again (rule 83: entrances
 * run once per mount). Drive a left-to-right clip, bar heights or dot opacity from it.
 * Reduced motion starts at 1.
 */
export function useDrawIn(ref: RefObject<Element | null>, { reduced = false, duration = 0.9, delay = 0, amount = 0.35 }: DrawInOptions = {}) {
  const progress = useMotionValue(0);
  const inView = useInView(ref, { once: true, amount });
  useEffect(() => {
    if (reduced) {
      progress.jump(1);
      return;
    }
    if (!inView) return;
    const controls = animate(progress, 1, { duration, delay, ease: ease.inOut });
    return () => controls.stop();
  }, [inView, reduced, progress, duration, delay]);
  return progress;
}

"use client";

import type { Transition } from "motion/react";
import { createContext, useCallback, useContext, useMemo, useState, type ReactNode } from "react";
import { smooth } from "../../lib/motion";

/**
 * The shared date range of a page of charts. Changing it is one coordinated beat: every chart
 * under the provider morphs on the same transition, starting in the same frame.
 *
 * Frozen contract (lane 5 → Range Picker, Metrics Dashboard):
 *   range       the selected range key, e.g. "7d"
 *   setRange    select another range
 *   beat        increments on every change; key per-change effects off it
 *   transition  the morph every chart under the provider uses
 *   compare     whether a previous-period series is shown
 *   setCompare  toggle it
 */
export type ChartRangeValue<R extends string = string> = {
  range: R;
  setRange: (range: R) => void;
  beat: number;
  transition: Transition;
  compare: boolean;
  setCompare: (compare: boolean) => void;
};

export const ChartRangeContext = createContext<ChartRangeValue | null>(null);

export type ChartRangeProviderProps<R extends string> = {
  /** Controlled range. */
  value?: R;
  /** Uncontrolled initial range. */
  defaultValue?: R;
  onValueChange?: (range: R) => void;
  compare?: boolean;
  defaultCompare?: boolean;
  onCompareChange?: (compare: boolean) => void;
  /** The morph shared by every chart below. Default `smooth`. */
  transition?: Transition;
  children: ReactNode;
};

export function ChartRangeProvider<R extends string>({
  value,
  defaultValue,
  onValueChange,
  compare: compareProp,
  defaultCompare = false,
  onCompareChange,
  transition = smooth,
  children,
}: ChartRangeProviderProps<R>) {
  const [inner, setInner] = useState(defaultValue as R);
  const [innerCompare, setInnerCompare] = useState(defaultCompare);
  const [beat, setBeat] = useState(0);
  const range = value ?? inner;
  const compare = compareProp ?? innerCompare;

  const setRange = useCallback(
    (next: R) => {
      if (next === range) return;
      setInner(next);
      setBeat((b) => b + 1);
      onValueChange?.(next);
    },
    [range, onValueChange],
  );
  const setCompare = useCallback(
    (next: boolean) => {
      setInnerCompare(next);
      onCompareChange?.(next);
    },
    [onCompareChange],
  );

  const ctx = useMemo(
    () => ({ range, setRange, beat, transition, compare, setCompare }) as unknown as ChartRangeValue,
    [range, setRange, beat, transition, compare, setCompare],
  );
  return <ChartRangeContext.Provider value={ctx}>{children}</ChartRangeContext.Provider>;
}

/** The surrounding range, or null outside a `ChartRangeProvider`. */
export function useChartRange<R extends string = string>() {
  return useContext(ChartRangeContext) as ChartRangeValue<R> | null;
}

/** The morph transition a chart should use: the provider's, else `fallback`. */
export function useChartTransition(fallback: Transition = smooth) {
  return useContext(ChartRangeContext)?.transition ?? fallback;
}

/**
 * The chart palette: six categorical hues in a fixed order, stepped separately for light and
 * dark and validated as a set (adjacent CVD ΔE ≥ 8.4, normal-vision ΔE ≥ 19.3, both themes).
 * Slots 3–5 sit under 3:1 on a white surface, which is why every chart ships a data table and
 * a legend: identity is never colour alone.
 *
 * They live here until `eased.css` carries them. Declared at zero specificity, so the same
 * variables in `eased.css` (or your own theme) win the moment they exist.
 */
const LIGHT = [
  "oklch(57.5% 0.163 255.5)", // blue
  "oklch(67.1% 0.175 40.6)", // orange
  "oklch(66.9% 0.141 162.1)", // aqua
  "oklch(76.4% 0.161 75.1)", // amber
  "oklch(71.6% 0.141 357.4)", // pink
  "oklch(52.7% 0.197 283.4)", // violet
];
const DARK = [
  "oklch(62.2% 0.161 255.1)",
  "oklch(62.2% 0.173 40.1)",
  "oklch(62.1% 0.128 163.1)",
  "oklch(67% 0.143 73.2)",
  "oklch(62.2% 0.171 0.8)",
  "oklch(67% 0.145 286.8)",
];

const vars = (colors: string[]) => colors.map((c, i) => `--eased-chart-${i + 1}:${c};`).join("");

/** The CSS the charts inject; also what to paste into `eased.css` to make the tokens global. */
export const CHART_TOKENS_CSS =
  `:where(:root){${vars(LIGHT)}--eased-chart-grid:var(--eased-line-subtle);--eased-chart-cursor:var(--eased-line-strong);}` +
  `:where(.dark,[data-theme="dark"]){${vars(DARK)}}`;

/**
 * Renders the chart tokens once per document (React 19 hoists and dedupes a `<style>` with
 * an `href`). Every chart renders it; you never need to.
 */
export function ChartTokens() {
  return (
    <style href="eased-chart-tokens" precedence="low">
      {CHART_TOKENS_CSS}
    </style>
  );
}

/** Number of categorical slots. A seventh series is not a generated hue: fold it into "Other". */
export const CHART_SLOTS = 6;

/**
 * The colour for series slot `n` (1-based) as a CSS variable. Slots past six fall back to
 * muted text rather than cycling, so two series never share a hue silently.
 */
export function chartColor(n: number) {
  return n >= 1 && n <= CHART_SLOTS ? `var(--eased-chart-${n})` : "var(--eased-text-muted)";
}
